1	import * as React from 'react';
2	import { composeEventHandlers } from '@radix-ui/primitive';
3	import { createContextScope } from '@radix-ui/react-context';
4	import { Primitive } from '@radix-ui/react-primitive';
5	import * as MenuPrimitive from '@radix-ui/react-menu';
6	import { createMenuScope } from '@radix-ui/react-menu';
7	import { useControllableState } from '@radix-ui/react-use-controllable-state';
8	import type { Scope } from '@radix-ui/react-context';
9	
10	type Direction = 'ltr' | 'rtl';
11	type Point = { x: number; y: number };
12	
13	/* -------------------------------------------------------------------------------------------------
14	 * ContextMenu
15	 * -----------------------------------------------------------------------------------------------*/
16	
17	const CONTEXT_MENU_NAME = 'ContextMenu';
18	
19	type ScopedProps<P> = P & { __scopeContextMenu?: Scope };
20	const [createContextMenuContext, createContextMenuScope] = createContextScope(CONTEXT_MENU_NAME, [
21	  createMenuScope,
22	]);
23	const useMenuScope = createMenuScope();
24	
25	interface ContextMenuContextValue {
26	  open: boolean;
27	  onOpenChange(open: boolean): void;
28	  modal: boolean;
29	  hasInteractedRef: React.RefObject<boolean>;
30	}
31	
32	const [ContextMenuProvider, useContextMenuContext] =
33	  createContextMenuContext<ContextMenuContextValue>(CONTEXT_MENU_NAME);
34	
35	interface ContextMenuProps {
36	  children?: React.ReactNode;
37	  open?: boolean;
38	  onOpenChange?(open: boolean): void;
39	  dir?: Direction;
40	  modal?: boolean;
41	}
42	
43	const ContextMenu: React.FC<ContextMenuProps> = (props: ScopedProps<ContextMenuProps>) => {
44	  const { __scopeContextMenu, children, onOpenChange, open: openProp, dir, modal = true } = props;
45	
46	  // OK to disable conditionally calling hooks here because they will always run
47	  // consistently in the same environment. Bundlers should be able to remove the
48	  // code block entirely in production.
49	  /* eslint-disable react-hooks/rules-of-hooks */
50	  const hasInteractedRef = React.useRef(false);
51	  if (process.env.NODE_ENV !== 'production') {
52	    const hasWarnedRef = React.useRef(false);
53	    React.useEffect(() => {
54	      if (openProp === true && !hasInteractedRef.current && !hasWarnedRef.current) {
55	        hasWarnedRef.current = true;
56	        // dev warning: open prop is controllable but its position has not been set
57	        // because the user has not interacted with the trigger. The controllable
58	        // state is only enabled so that the user can read or programatically close
59	        // the menu. Programatically opening the menu will anchor it to the most
60	        // recently interacted position.
61	        console.warn(
62	          'ContextMenu: The `open` prop has been set to `true` before the user has interacted with the trigger, so its position is indeterminate. This is likely unintended and will result in the menu being anchored to the top-left corner of the viewport.',
63	        );
64	      }
65	    }, [openProp]);
66	  }
67	  /* eslint-enable react-hooks/rules-of-hooks */
68	
69	  const [open, setOpen] = useControllableState({
70	    prop: openProp,
71	    defaultProp: false,
72	    onChange: onOpenChange,
73	    caller: CONTEXT_MENU_NAME,
74	  });
75	
76	  const menuScope = useMenuScope(__scopeContextMenu);
77	
78	  return (
79	    <ContextMenuProvider
80	      scope={__scopeContextMenu}
81	      open={open}
82	      onOpenChange={setOpen}
83	      modal={modal}
84	      hasInteractedRef={hasInteractedRef}
85	    >
86	      <MenuPrimitive.Root {...menuScope} dir={dir} open={open} onOpenChange={setOpen} modal={modal}>
87	        {children}
88	      </MenuPrimitive.Root>
89	    </ContextMenuProvider>
90	  );
91	};
92	
93	ContextMenu.displayName = CONTEXT_MENU_NAME;
94	
95	/* -------------------------------------------------------------------------------------------------
96	 * ContextMenuTrigger
97	 * -----------------------------------------------------------------------------------------------*/
98	
99	const TRIGGER_NAME = 'ContextMenuTrigger';
100	
101	type ContextMenuTriggerElement = React.ComponentRef<typeof Primitive.span>;
102	type PrimitiveSpanProps = React.ComponentPropsWithoutRef<typeof Primitive.span>;
103	interface ContextMenuTriggerProps extends PrimitiveSpanProps {
104	  disabled?: boolean;
105	}
106	
107	const ContextMenuTrigger = React.forwardRef<ContextMenuTriggerElement, ContextMenuTriggerProps>(
108	  (props: ScopedProps<ContextMenuTriggerProps>, forwardedRef) => {
109	    const { __scopeContextMenu, disabled = false, ...triggerProps } = props;
110	    const context = useContextMenuContext(TRIGGER_NAME, __scopeContextMenu);
111	    const menuScope = useMenuScope(__scopeContextMenu);
112	    const pointRef = React.useRef<Point>({ x: 0, y: 0 });
113	    const virtualRef = React.useRef({
114	      getBoundingClientRect: () => DOMRect.fromRect({ width: 0, height: 0, ...pointRef.current }),
115	    });
116	    const longPressTimerRef = React.useRef(0);
117	    const clearLongPress = React.useCallback(
118	      () => window.clearTimeout(longPressTimerRef.current),
119	      [],
120	    );
121	    const handleOpen = (event: React.MouseEvent | React.PointerEvent) => {
122	      context.hasInteractedRef.current = true;
123	      pointRef.current = { x: event.clientX, y: event.clientY };
124	      context.onOpenChange(true);
125	    };
126	
127	    React.useEffect(() => clearLongPress, [clearLongPress]);
128	    React.useEffect(() => void (disabled && clearLongPress()), [disabled, clearLongPress]);
129	
130	    return (
131	      <>
132	        <MenuPrimitive.Anchor {...menuScope} virtualRef={virtualRef} />
133	        <Primitive.span
134	          data-state={context.open ? 'open' : 'closed'}
135	          data-disabled={disabled ? '' : undefined}
136	          {...triggerProps}
137	          ref={forwardedRef}
138	          // prevent iOS context menu from appearing
139	          style={{ WebkitTouchCallout: 'none', ...props.style }}
140	          // if trigger is disabled, enable the native Context Menu
141	          onContextMenu={
142	            disabled
143	              ? props.onContextMenu
144	              : composeEventHandlers(props.onContextMenu, (event) => {
145	                  // clearing the long press here because some platforms already support
146	                  // long press to trigger a `contextmenu` event
147	                  clearLongPress();
148	                  handleOpen(event);
149	                  event.preventDefault();
150	                })
151	          }
152	          onPointerDown={
153	            disabled
154	              ? props.onPointerDown
155	              : composeEventHandlers(
156	                  props.onPointerDown,
157	                  whenTouchOrPen((event) => {
158	                    // clear the long press here in case there's multiple touch points
159	                    clearLongPress();
160	                    if (context.open) {
161	                      context.onOpenChange(false);
162	                    }
163	                    longPressTimerRef.current = window.setTimeout(() => handleOpen(event), 700);
164	                  }),
165	                )
166	          }
167	          onPointerMove={
168	            disabled
169	              ? props.onPointerMove
170	              : composeEventHandlers(props.onPointerMove, whenTouchOrPen(clearLongPress))
171	          }
172	          onPointerCancel={
173	            disabled
174	              ? props.onPointerCancel
175	              : composeEventHandlers(props.onPointerCancel, whenTouchOrPen(clearLongPress))
176	          }
177	          onPointerUp={
178	            disabled
179	              ? props.onPointerUp
180	              : composeEventHandlers(props.onPointerUp, whenTouchOrPen(clearLongPress))
181	          }
182	        />
183	      </>
184	    );
185	  },
186	);
187	
188	ContextMenuTrigger.displayName = TRIGGER_NAME;
