213	const CONTENT_NAME = 'ContextMenuContent';
214	
215	type ContextMenuContentElement = React.ComponentRef<typeof MenuPrimitive.Content>;
216	type MenuContentProps = React.ComponentPropsWithoutRef<typeof MenuPrimitive.Content>;
217	interface ContextMenuContentProps extends Omit<
218	  MenuContentProps,
219	  'onEntryFocus' | 'side' | 'sideOffset' | 'align'
220	> {}
221	
222	const ContextMenuContent = React.forwardRef<ContextMenuContentElement, ContextMenuContentProps>(
223	  (props: ScopedProps<ContextMenuContentProps>, forwardedRef) => {
224	    const { __scopeContextMenu, ...contentProps } = props;
225	    const context = useContextMenuContext(CONTENT_NAME, __scopeContextMenu);
226	    const menuScope = useMenuScope(__scopeContextMenu);
227	    const hasInteractedOutsideRef = React.useRef(false);
228	
229	    return (
230	      <MenuPrimitive.Content
231	        {...menuScope}
232	        {...contentProps}
233	        ref={forwardedRef}
234	        side="right"
235	        sideOffset={2}
236	        align="start"
237	        onCloseAutoFocus={(event) => {
238	          props.onCloseAutoFocus?.(event);
239	
240	          if (!event.defaultPrevented && hasInteractedOutsideRef.current) {
241	            event.preventDefault();
242	          }
243	
244	          hasInteractedOutsideRef.current = false;
245	        }}
246	        onInteractOutside={(event) => {
247	          props.onInteractOutside?.(event);
248	
249	          if (!event.defaultPrevented && !context.modal) hasInteractedOutsideRef.current = true;
250	        }}
251	        style={{
252	          ...props.style,
253	          // re-namespace exposed content custom properties
254	          ...{
255	            '--radix-context-menu-content-transform-origin': 'var(--radix-popper-transform-origin)',
256	            '--radix-context-menu-content-available-width': 'var(--radix-popper-available-width)',
257	            '--radix-context-menu-content-available-height': 'var(--radix-popper-available-height)',
258	            '--radix-context-menu-trigger-width': 'var(--radix-popper-anchor-width)',
259	            '--radix-context-menu-trigger-height': 'var(--radix-popper-anchor-height)',
260	          },
261	        }}
262	      />
263	    );
264	  },
265	);
266	
267	ContextMenuContent.displayName = CONTENT_NAME;
