87	const Menu: React.FC<MenuProps> = (props: ScopedProps<MenuProps>) => {
88	  const { __scopeMenu, open = false, children, dir, onOpenChange, modal = true } = props;
89	  const popperScope = usePopperScope(__scopeMenu);
90	  const [content, setContent] = React.useState<MenuContentElement | null>(null);
91	  const isUsingKeyboardRef = React.useRef(false);
92	  const handleOpenChange = useCallbackRef(onOpenChange);
93	  const direction = useDirection(dir);
94	
95	  React.useEffect(() => {
96	    // Capture phase ensures we set the boolean before any side effects execute
97	    // in response to the key or pointer event as they might depend on this value.
98	    const handleKeyDown = () => {
99	      isUsingKeyboardRef.current = true;
100	      document.addEventListener('pointerdown', handlePointer, { capture: true, once: true });
101	      document.addEventListener('pointermove', handlePointer, { capture: true, once: true });
102	    };
103	    const handlePointer = () => (isUsingKeyboardRef.current = false);
104	    document.addEventListener('keydown', handleKeyDown, { capture: true });
105	    return () => {
106	      document.removeEventListener('keydown', handleKeyDown, { capture: true });
107	      document.removeEventListener('pointerdown', handlePointer, { capture: true });
108	      document.removeEventListener('pointermove', handlePointer, { capture: true });
109	    };
