642	        dispatchDiscreteCustomEvent(menuItem, itemSelectEvent);
643	        if (itemSelectEvent.defaultPrevented) {
644	          isPointerDownRef.current = false;
645	        } else {
646	          rootContext.onClose();
647	        }
648	      }
649	    };
650	
651	    return (
652	      <MenuItemImpl
653	        {...itemProps}
654	        ref={composedRefs}
655	        disabled={disabled}
656	        onClick={composeEventHandlers(props.onClick, handleSelect)}
