199	     */
200	    React.useEffect(() => {
201	      return () => {
202	        if (!node) return;
203	        context.layers.delete(node);
204	        context.layersWithOutsidePointerEventsDisabled.delete(node);
205	        dispatchUpdate();
206	      };
207	    }, [node, context]);
208	
209	    React.useEffect(() => {
210	      const handleUpdate = () => force({});
211	      document.addEventListener(CONTEXT_UPDATE, handleUpdate);
212	      return () => document.removeEventListener(CONTEXT_UPDATE, handleUpdate);
213	    }, []);
214	
215	    return (
216	      <Primitive.div
217	        {...layerProps}
218	        ref={composedRefs}
219	        style={{
220	          pointerEvents: isBodyPointerEventsDisabled
221	            ? isPointerEventsEnabled
222	              ? 'auto'
223	              : 'none'
224	            : undefined,
225	          ...props.style,
226	        }}
227	        onFocusCapture={composeEventHandlers(props.onFocusCapture, focusOutside.onFocusCapture)}
228	        onBlurCapture={composeEventHandlers(props.onBlurCapture, focusOutside.onBlurCapture)}
229	        onPointerDownCapture={composeEventHandlers(
230	          props.onPointerDownCapture,
231	          pointerDownOutside.onPointerDownCapture,
232	        )}
233	      />
234	    );
235	  },
236	);
