238	DismissableLayer.displayName = DISMISSABLE_LAYER_NAME;
239	
240	/* -------------------------------------------------------------------------------------------------
241	 * DismissableLayerBranch
242	 * -----------------------------------------------------------------------------------------------*/
243	
244	const BRANCH_NAME = 'DismissableLayerBranch';
245	
246	type DismissableLayerBranchElement = React.ComponentRef<typeof Primitive.div>;
247	interface DismissableLayerBranchProps extends PrimitiveDivProps {}
248	
249	const DismissableLayerBranch = React.forwardRef<
250	  DismissableLayerBranchElement,
251	  DismissableLayerBranchProps
252	>((props, forwardedRef) => {
253	  const context = React.useContext(DismissableLayerContext);
254	  const ref = React.useRef<DismissableLayerBranchElement>(null);
255	  const composedRefs = useComposedRefs(forwardedRef, ref);
256	
257	  React.useEffect(() => {
258	    const node = ref.current;
259	    if (node) {
260	      context.branches.add(node);
261	      return () => {
262	        context.branches.delete(node);
263	      };
264	    }
265	  }, [context.branches]);
266	
267	  return <Primitive.div {...props} ref={composedRefs} />;
268	});
269	
270	DismissableLayerBranch.displayName = BRANCH_NAME;
271	
272	/* -----------------------------------------------------------------------------------------------*/
273	
274	/**
275	 * Registers a node as a "dismiss surface" for the enclosing DismissableLayer
276	 */
277	function useDismissableLayerSurface(): React.RefCallback<DismissableLayerBranchElement> {
278	  const context = React.useContext(DismissableLayerContext);
279	  const [node, setNode] = React.useState<DismissableLayerBranchElement | null>(null);
280	
281	  React.useEffect(() => {
282	    if (!node) {
283	      return;
284	    }
285	    context.dismissableSurfaces.add(node);
286	    return () => {
287	      context.dismissableSurfaces.delete(node);
288	    };
289	  }, [node, context.dismissableSurfaces]);
290	
291	  return setNode;
292	}
293	
294	type PointerDownOutsideEvent = CustomEvent<{ originalEvent: PointerEvent }>;
295	type FocusOutsideEvent = CustomEvent<{ originalEvent: FocusEvent }>;
296	
297	const IS_TRUE = () => true;
298	
299	/**
300	 * Listens for `pointerdown` outside a react subtree. We detect the start of the interaction on
301	 * `pointerdown`, then wait for `click` so external code can intercept later mouse events.
302	 * Returns props to pass to the node we want to check for outside events.
303	 */
304	function usePointerDownOutside(
305	  onPointerDownOutside: ((event: PointerDownOutsideEvent) => void) | undefined,
306	  args: {
307	    ownerDocument: Document | undefined;
308	    deferPointerDownOutside: boolean;
309	    isDeferredPointerDownOutsideRef: React.RefObject<boolean>;
310	    dismissableSurfaces: Set<DismissableLayerBranchElement>;
311	    shouldHandlePointerDownOutside?: (target: EventTarget | null) => boolean;
312	  },
313	) {
314	  const {
315	    ownerDocument = globalThis?.document,
316	    deferPointerDownOutside = false,
317	    isDeferredPointerDownOutsideRef,
318	    dismissableSurfaces,
319	    shouldHandlePointerDownOutside = IS_TRUE,
320	  } = args;
321	  const handlePointerDownOutside = useCallbackRef(onPointerDownOutside) as EventListener;
322	  const isPointerInsideReactTreeRef = React.useRef(false);
323	  const isPointerDownOutsideRef = React.useRef(false);
324	  const interceptedOutsideInteractionEventsRef = React.useRef<Map<string, boolean>>(new Map());
325	  const handleClickRef = React.useRef(() => {});
326	
327	  React.useEffect(() => {
328	    function resetOutsideInteraction() {
329	      isPointerDownOutsideRef.current = false;
330	      isDeferredPointerDownOutsideRef.current = false;
331	      interceptedOutsideInteractionEventsRef.current.clear();
332	    }
333	
334	    function isOutsideInteractionIntercepted() {
335	      return Array.from(interceptedOutsideInteractionEventsRef.current.values()).some(Boolean);
336	    }
337	
338	    function handleInteractionCapture(event: Event) {
339	      if (!isPointerDownOutsideRef.current) {
340	        return;
341	      }
342	
343	      const target = event.target;
344	      const isDismissableSurface =
345	        target instanceof Node &&
346	        [...dismissableSurfaces].some((surface) => surface.contains(target as Node));
347	
348	      if (!isDismissableSurface) {
349	        interceptedOutsideInteractionEventsRef.current.set(event.type, true);
350	      }
351	
352	      if (event.type === 'click') {
353	        window.setTimeout(() => {
354	          if (isPointerDownOutsideRef.current) {
355	            handleClickRef.current();
356	          }
357	        }, 0);
358	      }
359	    }
360	
361	    function handleInteractionBubble(event: Event) {
362	      if (isPointerDownOutsideRef.current) {
363	        interceptedOutsideInteractionEventsRef.current.set(event.type, false);
364	      }
365	    }
366	
367	    const handlePointerDown = (event: PointerEvent) => {
368	      if (event.target && !isPointerInsideReactTreeRef.current) {
369	        if (!shouldHandlePointerDownOutside(event.target)) {
370	          ownerDocument.removeEventListener('click', handleClickRef.current);
371	          resetOutsideInteraction();
372	          isPointerInsideReactTreeRef.current = false;
373	          return;
374	        }
375	
376	        const eventDetail = { originalEvent: event };
377	        isPointerDownOutsideRef.current = true;
378	        isDeferredPointerDownOutsideRef.current = deferPointerDownOutside && event.button === 0;
379	        interceptedOutsideInteractionEventsRef.current.clear();
380	
381	        function handleAndDispatchPointerDownOutsideEvent() {
382	          ownerDocument.removeEventListener('click', handleClickRef.current);
383	          const wasOutsideInteractionIntercepted = isOutsideInteractionIntercepted();
384	          resetOutsideInteraction();
385	
386	          if (!wasOutsideInteractionIntercepted) {
387	            handleAndDispatchCustomEvent(
388	              POINTER_DOWN_OUTSIDE,
389	              handlePointerDownOutside,
390	              eventDetail,
391	              { discrete: true },
392	            );
393	          }
394	        }
395	
396	        /**
397	         * When deferring, we need to wait for a click event because:
398	         *
399	         * 1. On touch devices, browsers implement a ~350ms delay between the
400	         *    time the user stops touching the display and when the browser
401	         *    executes events. We need to ensure we don't reactivate
402	         *    pointer-events within this timeframe otherwise the browser may
403	         *    execute events that should have been prevented.
404	         *
405	         * 2. Browser extensions and other third-party code may call
406	         *    `stopPropagation` on later mouse events like `mousedown`,
407	         *    `mouseup`, or `click`. Waiting lets those intercepted events
408	         *    cancel the outside interaction before we dismiss the layer. See
409	         *    https://github.com/radix-ui/primitives/issues/2055
410	         *
411	         * Additionally, this also lets us deal automatically with cancellations
412	         * when a click event isn't raised because the page was considered
413	         * scrolled/drag-scrolled, long-pressed, etc.
414	         *
415	         * This is why we also continuously remove the previous listener,
416	         * because we cannot be certain that it was raised, and therefore
417	         * cleaned-up.
418	         *
419	         * For non-primary buttons, we dispatch the event immediately because we
420	         * cannot be certain that the event was canceled.
421	         */
422	        if (!deferPointerDownOutside || event.button !== 0) {
423	          handleAndDispatchPointerDownOutsideEvent();
424	        } else {
425	          ownerDocument.removeEventListener('click', handleClickRef.current);
426	          handleClickRef.current = handleAndDispatchPointerDownOutsideEvent;
427	          ownerDocument.addEventListener('click', handleClickRef.current, { once: true });
428	        }
429	      } else {
430	        // We need to remove the event listener in case the outside click has been canceled.
431	        // See: https://github.com/radix-ui/primitives/issues/2171
432	        ownerDocument.removeEventListener('click', handleClickRef.current);
433	        resetOutsideInteraction();
434	      }
435	      isPointerInsideReactTreeRef.current = false;
436	    };
437	
438	    const outsideInteractionEvents = [
439	      'pointerup',
440	      'mousedown',
441	      'mouseup',
442	      'touchstart',
443	      'touchend',
444	      'click',
445	    ];
446	
447	    for (const eventName of outsideInteractionEvents) {
448	      ownerDocument.addEventListener(eventName, handleInteractionCapture, true);
449	      ownerDocument.addEventListener(eventName, handleInteractionBubble);
450	    }
451	
452	    /**
453	     * if this hook executes in a component that mounts via a `pointerdown` event, the event
454	     * would bubble up to the document and trigger a `pointerDownOutside` event. We avoid
455	     * this by delaying the event listener registration on the document.
456	     * This is not React specific, but rather how the DOM works, ie:
457	     * ```
458	     * button.addEventListener('pointerdown', () => {
459	     *   console.log('I will log');
460	     *   document.addEventListener('pointerdown', () => {
461	     *     console.log('I will also log');
462	     *   })
463	     * });
464	     */
465	    const timerId = window.setTimeout(() => {
466	      ownerDocument.addEventListener('pointerdown', handlePointerDown);
467	    }, 0);
468	    return () => {
469	      window.clearTimeout(timerId);
470	      ownerDocument.removeEventListener('pointerdown', handlePointerDown);
471	      ownerDocument.removeEventListener('click', handleClickRef.current);
472	      for (const eventName of outsideInteractionEvents) {
473	        ownerDocument.removeEventListener(eventName, handleInteractionCapture, true);
474	        ownerDocument.removeEventListener(eventName, handleInteractionBubble);
475	      }
476	    };
477	  }, [
478	    ownerDocument,
479	    handlePointerDownOutside,
480	    deferPointerDownOutside,
481	    isDeferredPointerDownOutsideRef,
482	    dismissableSurfaces,
483	    shouldHandlePointerDownOutside,
484	  ]);
485	
486	  return {
487	    // ensures we check React component tree (not just DOM tree)
488	    onPointerDownCapture: () => (isPointerInsideReactTreeRef.current = true),
489	  };
490	}
491	
492	/**
493	 * Listens for when focus happens outside a react subtree.
494	 * Returns props to pass to the root (node) of the subtree we want to check.
495	 */
496	function useFocusOutside(
497	  onFocusOutside?: (event: FocusOutsideEvent) => void,
498	  ownerDocument: Document = globalThis?.document,
499	) {
500	  const handleFocusOutside = useCallbackRef(onFocusOutside) as EventListener;
501	  const isFocusInsideReactTreeRef = React.useRef(false);
502	
503	  React.useEffect(() => {
504	    const handleFocus = (event: FocusEvent) => {
505	      if (event.target && !isFocusInsideReactTreeRef.current) {
506	        const eventDetail = { originalEvent: event };
507	        handleAndDispatchCustomEvent(FOCUS_OUTSIDE, handleFocusOutside, eventDetail, {
508	          discrete: false,
509	        });
510	      }
511	    };
512	    ownerDocument.addEventListener('focusin', handleFocus);
513	    return () => ownerDocument.removeEventListener('focusin', handleFocus);
514	  }, [ownerDocument, handleFocusOutside]);
515	
516	  return {
517	    onFocusCapture: () => (isFocusInsideReactTreeRef.current = true),
518	    onBlurCapture: () => (isFocusInsideReactTreeRef.current = false),
519	  };
520	}
521	
522	function dispatchUpdate() {
523	  const event = new CustomEvent(CONTEXT_UPDATE);
524	  document.dispatchEvent(event);
525	}
526	
527	function handleAndDispatchCustomEvent<E extends CustomEvent, OriginalEvent extends Event>(
528	  name: string,
529	  handler: ((event: E) => void) | undefined,
530	  detail: { originalEvent: OriginalEvent } & (E extends CustomEvent<infer D> ? D : never),
531	  { discrete }: { discrete: boolean },
532	) {
533	  const target = detail.originalEvent.target;
534	  const event = new CustomEvent(name, { bubbles: false, cancelable: true, detail });
535	  if (handler) target.addEventListener(name, handler as EventListener, { once: true });
536	
537	  if (discrete) {
538	    dispatchDiscreteCustomEvent(target, event);
539	  } else {
540	    target.dispatchEvent(event);
541	  }
542	}
543	
544	const Root = DismissableLayer;
545	const Branch = DismissableLayerBranch;
546	
547	export {
548	  DismissableLayer,
549	  DismissableLayerBranch,
550	  useDismissableLayerSurface,
551	  //
552	  Root,
553	  Branch,
554	};
555	export type { DismissableLayerProps };
