426	  name: 'transformOrigin',
427	  options,
428	  fn(data) {
429	    const { placement, rects, middlewareData } = data;
430	
431	    const cannotCenterArrow = middlewareData.arrow?.centerOffset !== 0;
432	    const isArrowHidden = cannotCenterArrow;
433	    const arrowWidth = isArrowHidden ? 0 : options.arrowWidth;
434	    const arrowHeight = isArrowHidden ? 0 : options.arrowHeight;
435	
436	    const [placedSide, placedAlign] = getSideAndAlignFromPlacement(placement);
437	    const noArrowAlign = { start: '0%', center: '50%', end: '100%' }[placedAlign];
438	
439	    const arrowXCenter = (middlewareData.arrow?.x ?? 0) + arrowWidth / 2;
440	    const arrowYCenter = (middlewareData.arrow?.y ?? 0) + arrowHeight / 2;
441	
442	    let x = '';
443	    let y = '';
444	
445	    if (placedSide === 'bottom') {
446	      x = isArrowHidden ? noArrowAlign : `${arrowXCenter}px`;
447	      y = `${-arrowHeight}px`;
448	    } else if (placedSide === 'top') {
449	      x = isArrowHidden ? noArrowAlign : `${arrowXCenter}px`;
450	      y = `${rects.floating.height + arrowHeight}px`;
451	    } else if (placedSide === 'right') {
452	      x = `${-arrowHeight}px`;
453	      y = isArrowHidden ? noArrowAlign : `${arrowYCenter}px`;
454	    } else if (placedSide === 'left') {
455	      x = `${rects.floating.width + arrowHeight}px`;
456	      y = isArrowHidden ? noArrowAlign : `${arrowYCenter}px`;
457	    }
458	    return { data: { x, y } };
459	  },
460	});
