1	import * as React from 'react';
2	import { useLayoutEffect } from '@radix-ui/react-use-layout-effect';
3	
4	// Prevent bundlers from trying to optimize the import
5	const useInsertionEffect: typeof useLayoutEffect =
6	  (React as any)[' useInsertionEffect '.trim().toString()] || useLayoutEffect;
7	
8	type ChangeHandler<T> = (state: T) => void;
9	type SetStateFn<T> = React.Dispatch<React.SetStateAction<T>>;
10	
11	interface UseControllableStateParams<T> {
12	  prop?: T | undefined;
13	  defaultProp: T;
14	  onChange?: ChangeHandler<T>;
15	  caller?: string;
16	}
17	
18	export function useControllableState<T>({
19	  prop,
20	  defaultProp,
21	  onChange = () => {},
22	  caller,
23	}: UseControllableStateParams<T>): [T, SetStateFn<T>] {
24	  const [uncontrolledProp, setUncontrolledProp, onChangeRef] = useUncontrolledState({
25	    defaultProp,
26	    onChange,
27	  });
28	  const isControlled = prop !== undefined;
29	  const value = isControlled ? prop : uncontrolledProp;
30	
31	  // OK to disable conditionally calling hooks here because they will always run
32	  // consistently in the same environment. Bundlers should be able to remove the
33	  // code block entirely in production.
34	  /* eslint-disable react-hooks/rules-of-hooks */
35	  if (process.env.NODE_ENV !== 'production') {
36	    const isControlledRef = React.useRef(prop !== undefined);
37	    React.useEffect(() => {
38	      const wasControlled = isControlledRef.current;
39	      if (wasControlled !== isControlled) {
40	        const from = wasControlled ? 'controlled' : 'uncontrolled';
41	        const to = isControlled ? 'controlled' : 'uncontrolled';
42	        console.warn(
43	          `${caller} is changing from ${from} to ${to}. Components should not switch from controlled to uncontrolled (or vice versa). Decide between using a controlled or uncontrolled value for the lifetime of the component.`,
44	        );
45	      }
46	      isControlledRef.current = isControlled;
47	    }, [isControlled, caller]);
48	  }
49	  /* eslint-enable react-hooks/rules-of-hooks */
50	
51	  const setValue = React.useCallback<SetStateFn<T>>(
52	    (nextValue) => {
53	      if (isControlled) {
54	        const value = isFunction(nextValue) ? nextValue(prop) : nextValue;
55	        if (value !== prop) {
56	          onChangeRef.current?.(value);
57	        }
58	      } else {
59	        setUncontrolledProp(nextValue);
60	      }
61	    },
62	    [isControlled, prop, setUncontrolledProp, onChangeRef],
63	  );
64	
65	  return [value, setValue];
66	}
67	
68	function useUncontrolledState<T>({
69	  defaultProp,
70	  onChange,
71	}: Omit<UseControllableStateParams<T>, 'prop'>): [
72	  Value: T,
73	  setValue: React.Dispatch<React.SetStateAction<T>>,
74	  OnChangeRef: React.RefObject<ChangeHandler<T> | undefined>,
75	] {
76	  const [value, setValue] = React.useState(defaultProp);
77	  const prevValueRef = React.useRef(value);
78	
79	  const onChangeRef = React.useRef(onChange);
80	  useInsertionEffect(() => {
81	    onChangeRef.current = onChange;
82	  }, [onChange]);
83	
84	  React.useEffect(() => {
85	    if (prevValueRef.current !== value) {
86	      onChangeRef.current?.(value);
87	      prevValueRef.current = value;
88	    }
89	  }, [value, prevValueRef]);
90	
91	  return [value, setValue, onChangeRef];
92	}
