import * as React from 'react';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, describe, it, expect } from 'vitest';
import * as ContextMenu from './context-menu';

const TRIGGER_TEXT = 'Right click here';
const ITEM_TEXT = 'Item';

function ContextMenuTest(props: React.ComponentProps<typeof ContextMenu.Root>) {
  return (
    <ContextMenu.Root {...props}>
      <ContextMenu.Trigger>{TRIGGER_TEXT}</ContextMenu.Trigger>
      <ContextMenu.Portal>
        <ContextMenu.Content>
          <ContextMenu.Item>{ITEM_TEXT}</ContextMenu.Item>
        </ContextMenu.Content>
      </ContextMenu.Portal>
    </ContextMenu.Root>
  );
}

afterEach(cleanup);

describe('reposition on second right click', () => {
  it('repositions the menu when right-clicked again at a different point while open', async () => {
    render(<ContextMenuTest />);
    fireEvent.contextMenu(screen.getByText(TRIGGER_TEXT), { clientX: 10, clientY: 10 });
    await waitFor(() => expect(screen.getByRole('menu')).toBeInTheDocument());

    const wrapper = document.querySelector('[data-radix-popper-content-wrapper]') as HTMLElement;
    await waitFor(() => expect(wrapper.style.transform).toContain('10px'));
    const firstTransform = wrapper.style.transform;
    console.log('first transform', firstTransform);

    fireEvent.contextMenu(screen.getByText(TRIGGER_TEXT), { clientX: 300, clientY: 300 });
    await waitFor(() => expect(screen.getByRole('menu')).toBeInTheDocument());

    await waitFor(() => {
      const w = document.querySelector('[data-radix-popper-content-wrapper]') as HTMLElement;
      console.log('current transform', w.style.transform);
      expect(w.style.transform).not.toEqual(firstTransform);
    });
  });
});
