  return (
    <>
      <MenuPrimitive.Anchor {...menuScope} virtualRef={virtualRef} />
      <Primitive.span
        data-state={context.open ? 'open' : 'closed'}
        data-disabled={disabled ? '' : undefined}
        {...triggerProps}
        ref={forwardedRef}
        // prevent iOS context menu from appearing
        style={{ WebkitTouchCallout: 'none', ...props.style }}
        // if trigger is disabled, enable the native Context Menu
        onContextMenu={
          disabled
            ? props.onContextMenu
            : composeEventHandlers(props.onContextMenu, (event) => {
                // clearing the long press here because some platforms already support
                // long press to trigger a `contextmenu` event
                clearLongPress();
                // if the menu is already open, close it first (flushing synchronously
                // so the state change actually commits) before re-opening it below at
                // the new coordinates. Otherwise, since `open` is already `true`, the
                // reopen would be a no-op and the menu would stay anchored to its
                // original position.
                if (context.open) {
                  flushSync(() => context.onOpenChange(false));
                }
                handleOpen(event);
                event.preventDefault();
              })
        }
        onPointerDown={
          disabled
            ? props.onPointerDown
            : composeEventHandlers(
                props.onPointerDown,
                whenTouchOrPen((event) => {
                  // clear the long press here in case there's multiple touch points
                  clearLongPress();
                  if (context.open) {
                    context.onOpenChange(false);
                  }
                  longPressTimerRef.current = window.setTimeout(() => handleOpen(event), 700);
                }),
              )
        }
        onPointerMove={
          disabled
            ? props.onPointerMove
            : composeEventHandlers(props.onPointerMove, whenTouchOrPen(clearLongPress))
        }
        onPointerCancel={
          disabled
            ? props.onPointerCancel
            : composeEventHandlers(props.onPointerCancel, whenTouchOrPen(clearLongPress))
        }
        onPointerUp={
          disabled
            ? props.onPointerUp
            : composeEventHandlers(props.onPointerUp, whenTouchOrPen(clearLongPress))
        }
      />
    </>
  );
},

